            if let child = sceInvokeChildFits, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData)
                return true
            }
            return false
        }
        if invokeID.utf8.elementsEqual("over".utf8) {
            if let child = sceInvokeChildOver, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData)
                return true
            }
            return false
        }
        if invokeID.utf8.elementsEqual("wide".utf8) {
            if let child = sceInvokeChildWide, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData)
                return true
            }
            return false
        }
        return false
    }

    /// Whether `#_<invokeid>` names an invocation running now (W3C SCXML 6.4 + C.1):
    /// one whose session has reached its final state has ended, and a send naming it
    /// is reported when it is made.
    public func isInvocationRunning(_ invokeID: String) -> Bool {
        if invokeID.utf8.elementsEqual("fits".utf8) {
            return sceInvokeChildFits.map { !$0.isInFinalState } ?? false
        }
        if invokeID.utf8.elementsEqual("over".utf8) {
            return sceInvokeChildOver.map { !$0.isInFinalState } ?? false
        }
        if invokeID.utf8.elementsEqual("wide".utf8) {
            return sceInvokeChildWide.map { !$0.isInFinalState } ?? false
        }
        return false
    }

    /// Whether a session id names a child of this machine that is running now
    /// (W3C SCXML C.1): the test `deliverToChildSession` makes.
    public func isChildSessionRunning(_ childSessionID: String) -> Bool {
        if childSessionID.isEmpty {
            return false
        }
        if let session = activeInvokes["fits"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildFits.map { !$0.isInFinalState } ?? false
        }
        if let session = activeInvokes["over"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildOver.map { !$0.isInFinalState } ?? false
        }
        if let session = activeInvokes["wide"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildWide.map { !$0.isInFinalState } ?? false
        }
        return false
    }

    /// Delivers an event addressed to a child's published location (W3C SCXML C.1).
    /// The parent mints `parentSession.invokeId` for each child and that id is what the
    /// child's `_ioprocessors` entry names, so a `<send>` whose target decodes to one of
    /// them is addressed to that child and not to this machine. False names no live
    /// child of ours, and the event takes the ordinary external path.
    public func deliverToChildSession(childSessionID: String, eventName: String, eventData: String) -> Bool {
        if !isChildSessionRunning(childSessionID) {
            return false
        }
        if let session = activeInvokes["fits"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildFits {
            deliverToChild(child, eventName: eventName, eventData: eventData)
            return true
        }
        if let session = activeInvokes["over"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildOver {
            deliverToChild(child, eventName: eventName, eventData: eventData)
            return true
        }
        if let session = activeInvokes["wide"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildWide {
            deliverToChild(child, eventName: eventName, eventData: eventData)
            return true
        }
        return false
    }


    /// Enters one state (W3C SCXML 3.8): adds it to the configuration, runs its
    /// `<onentry>`, and its `<initial>` transition's content when its initial
    /// state is entered by default.
    public func executeEntryActions(_ state: StaticInvokeStringState, engine: Engine<StaticInvokeStringPolicy>, isDefaultEntry: Bool) {
        switch state {
        case .running:
            // W3C SCXML 6.4: an <invoke> starts at the end of the macrostep, so its
            // entry is deferred, and a state that exits before then never starts it.
            do {
                sceInvokeStartsFits += 1
                let generatedInvokeID = "running.\(sceInvokeStartsFits).fits"
                deferInvoke(&pendingInvokes, PendingInvoke(
                    invokeID: generatedInvokeID,
                    state: .running,
                    documentID: "fits"
                ))
            }
            // W3C SCXML 6.4: an <invoke> starts at the end of the macrostep, so its
            // entry is deferred, and a state that exits before then never starts it.
            do {
                sceInvokeStartsOver += 1
                let generatedInvokeID = "running.\(sceInvokeStartsOver).over"
                deferInvoke(&pendingInvokes, PendingInvoke(
                    invokeID: generatedInvokeID,
                    state: .running,
                    documentID: "over"
                ))
            }
            // W3C SCXML 6.4: an <invoke> starts at the end of the macrostep, so its
            // entry is deferred, and a state that exits before then never starts it.
            do {
                sceInvokeStartsWide += 1
                let generatedInvokeID = "running.\(sceInvokeStartsWide).wide"
                deferInvoke(&pendingInvokes, PendingInvoke(
                    invokeID: generatedInvokeID,
                    state: .running,
                    documentID: "wide"
                ))
            }
        default:
            break  // No entry actions
        }
    }

    /// Runs a `<history>`'s default transition content (W3C SCXML 3.10.2), after
    /// its parent's onentry (and after the parent's own `<initial>` content) when
    /// the history was taken with nothing recorded. The engine asks for it by the
    /// entry set's defaultHistoryContent answer; a history that restored what it
    /// recorded runs nothing.
    public func executeHistoryDefaultContent(_ history: HistoryID, engine: Engine<StaticInvokeStringPolicy>) {
        // W3C SCXML 3.10.2: no <history> in this document has default content.
    }

    /// Exits one state (W3C SCXML 3.9): records its histories, runs its `<onexit>`,
    /// cancels its invocations and removes it from the configuration, in
    /// §scxml-D-exitStates's order.
    public func executeExitActions(_ state: StaticInvokeStringState, engine: Engine<StaticInvokeStringPolicy>, configurationBeforeExit: [StaticInvokeStringState]) {
        // §scxml-D-exitStates orders one state's exit as onexit, then cancelInvoke,
        // then configuration.delete(s), so `In(s)` inside s's own handler is true:
        // the <onexit> switch comes first and the removal from the configuration
        // last.
        switch state {
        default:
            break  // No exit actions
        }
        // W3C SCXML 6.4: the invocations of an exited state end with it: one not yet
        // started never starts, and a running session is exited, its states' <onexit>
        // run, before it is dropped. What that exit sends to #_parent is dropped with
        // it (test252).
        switch state {
        case .running:
            cancelInvokesForState(&pendingInvokes, .running)
            sceInvokeChildFits?.stop()
            sceInvokeChildFits = nil
            activeInvokes["fits"] = nil
            sceInvokeDoneFits = false
            sceInvokeChildOver?.stop()
            sceInvokeChildOver = nil
            activeInvokes["over"] = nil
            sceInvokeDoneOver = false
            sceInvokeChildWide?.stop()
            sceInvokeChildWide = nil
            activeInvokes["wide"] = nil
            sceInvokeDoneWide = false
        default:
            break  // No invocations to cancel
        }
    }



    /// Appendix D selectTransitions, the half only this document can answer: the
    /// first of `state`'s own transitions, in document order, that `event` enables
    /// and whose guard holds. The engine walks the atomic states and their
    /// ancestors and keeps the ordered set; the null event asks for eventless
    /// transitions.
    public func firstEnabledTransition(
        _ state: StaticInvokeStringState,
        event: StaticInvokeStringEvent,
        engine: Engine<StaticInvokeStringPolicy>
    ) -> EnabledTransition<StaticInvokeStringState>? {
        switch state {
        case .running:
            if event == .doneInvokeFits {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 0,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .doneInvokeOver {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 1,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .doneInvokeWide {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 2,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .errorExecution {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 3,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
        default:
            break
        }
        return nil
    }

